import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let ABC be a right triangle with legs {a} and {b}, and let R be a rectangle with side lengths {rect_w} and {rect_h}. In ABC, draw a segment parallel to the hypotenuse that partitions the triangle into a smaller right triangle U1 and a trapezoid V1. In the rectangle, draw a segment from a point X on a side of length {rect_w} to the adjacent vertex so that R is partitioned into a right triangle U2 (with right angle at that vertex) and a trapezoid V2; thus the legs of U2 have lengths {rect_h} and {rect_w} - x for some x with 0 < x < {rect_w}. Suppose U1 is similar to U2. Among all such choices of segments, choose the one that minimizes the absolute difference between the perimeters of V1 and V2. In this minimizing configuration, the area of U1 can be written as m/n in lowest terms. Find m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a Pythagorean right triangle (a,b,c) and a rectangle (P=rect_w, Q=rect_h)
# so that there is a unique minimizing configuration where U1~U2 and the perimeters of V1 and V2 match.
# The construction enforces 0 < k < 1 and a valid triangle piece in the rectangle (x in (0,P)).
from fractions import Fraction
triples = [
    (3,4,5), (5,12,13), (8,15,17), (7,24,25), (9,40,41), (12,35,37),
    (20,21,29), (28,45,53), (11,60,61), (16,63,65)
]
# Try multiple attempts to find valid parameters
for _ in range(200):
    a,b,c = rng.choice(triples)
    # Scale the triple to vary difficulty
    s = rng.randint(1, 3)
    a *= s; b *= s; c *= s
    # Ensure a <= b (naming convention)
    if a > b:
        a,b = b,a
    # Try to pick a rectangle height Q and width P satisfying feasibility
    # Constraints for P in terms of Q:
    # Let r = (b + c - a)/b
    # Lower bounds: P > (a/b)Q and P > c - (Q/2)*r
    # Upper bound:  P < (a + b + c)/2 - (Q/2)*r
    r_num = b + c - a
    r_den = b
    # Sample Q in a reasonable range; keep modest sizes to avoid huge numbers
    for _q in range(60):
        Q = rng.randint(1, max(3, b))
        P_lower1 = Fraction(a*Q, b)
        P_lower2 = Fraction(c,1) - Fraction(Q*r_num, 2*r_den)
        P_upper  = Fraction(a + b + c, 2) - Fraction(Q*r_num, 2*r_den)
        # We need an integer P with max(LBs) < P < U
        L = max(P_lower1, P_lower2)
        U = P_upper
        # Compute smallest integer strictly greater than L
        l_floor = L.numerator // L.denominator
        P_min = l_floor + 1
        # Compute largest integer strictly less than U
        u_floor = U.numerator // U.denominator
        if U.numerator % U.denominator == 0:
            P_max = u_floor - 1
        else:
            P_max = u_floor
        if P_min <= P_max and P_min >= 1:
            P = rng.randint(P_min, P_max)
            # Check x = P - (a/b)Q > 0
            if P*b - a*Q <= 0:
                continue
            # Compute k from perimeter matching at optimum
            # N = 2P + Q*( (b+c-a)/b ) - (a + b + c)
            # D = c - a - b (negative)
            N = Fraction(2*P,1) + Fraction(Q*(b + c - a), b) - Fraction(a + b + c, 1)
            D = Fraction(c - a - b, 1)
            k = N / D
            if not (k > 0 and k < 1):
                continue
            return {'a': a, 'b': b, 'rect_w': P, 'rect_h': Q}
# Fallback deterministic assignment if random attempts fail (very unlikely)
# Use a=3,b=4,c=5; choose Q=2,P=4 which we know works, yields k=1/2
return {'a': 3, 'b': 4, 'rect_w': 4, 'rect_h': 2}

    def verifier(assign):
# Recompute, validate, and return (True, answer) or (False, None) with comments.
from fractions import Fraction
import math
try:
    a = int(assign['a']); b = int(assign['b']); P = int(assign['rect_w']); Q = int(assign['rect_h'])
except Exception:
    # Missing or invalid fields
    return (False, None)
if a <= 0 or b <= 0 or P <= 0 or Q <= 0:
    return (False, None)
# Ensure right triangle hypotenuse is integer (Pythagorean triple)
c2 = a*a + b*b
c = int(math.isqrt(c2))
if c*c != c2:
    # Not an integer hypotenuse; our derivation assumes integer c for rationality and clean algebra
    return (False, None)
# Ensure a <= b for the orientation chosen; swap if needed
if a > b:
    a, b = b, a
# Triangle similarity U1~U2 requires U2 legs ratio Q/(P-x) = b/a => x = P - (a/b)Q; enforce x in (0,P)
x = Fraction(P*b - a*Q, b)
if not (x > 0 and x < P):
    return (False, None)
# Compute minimizing k by equating perimeters P(V1)=P(V2), since |difference| is minimized there and P(V1) is affine in k
# Perimeter of V1: P1 = c(1+k) + (a+b)(1-k)
# Perimeter of V2: P2 = P + x + Q + sqrt((P-x)^2 + Q^2)
# Using U1~U2, P-x = (a/b)Q so the slanted side equals (Q*c)/b and x cancels from P2: P2 = 2P + Q*(1 - a/b + c/b)
P2 = Fraction(2*P,1) + Fraction(Q*(b + c - a), b)
D = Fraction(c - a - b, 1)  # negative
N = P2 - Fraction(a + b + c, 1)
k = N / D
if not (k > 0 and k < 1):
    # Invalid geometry configuration; generator should avoid this
    return (False, None)
# Verify perimeters match at this k
P1 = Fraction(c,1)*(1 + k) + Fraction(a + b,1)*(1 - k)
if P1 != P2:
    return (False, None)
# Area of U1 is (ab/2) * k^2
area = Fraction(a*b, 2) * k * k
# Reduce to lowest terms via Fraction
m = area.numerator
n = area.denominator
if m <= 0 or n <= 0:
    return (False, None)
answer = m + n
return True, int(answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

